// Bundles binary PDF assets (Noto TTFs, stamp PNG) as base64 TS constants so
// serverless functions always ship them: file-tracing does not follow
// fs.readFileSync, so disk reads work locally but 404/missing-file in
// production bundles. Generated file is gitignored and rebuilt on postinstall.
// Usage: npx tsx scripts/embed-assets.ts (idempotent; prints sizes, writes nothing else).
import fs from "node:fs";
import path from "node:path";

const ROOT = path.join(import.meta.dirname, "..");
const OUT = path.join(ROOT, "src", "lib", "receipts", "embedded-assets.ts");

const INPUTS = {
  NOTO_REGULAR_B64: "src/lib/receipts/fonts/NotoSans-Regular.ttf",
  NOTO_BOLD_B64: "src/lib/receipts/fonts/NotoSans-Bold.ttf",
  STAMP_PNG_B64: "src/lib/receipts/belgrove-stamp-and-signature.png",
} as const;

async function main() {
  let out = "// GENERATED by scripts/embed-assets.ts — do not edit by hand.\n";
  out += "// Base64 PDF assets (fonts, stamp) so serverless bundles always ship them.\n";
  for (const [key, rel] of Object.entries(INPUTS)) {
    const buf = fs.readFileSync(path.join(ROOT, rel));
    out += `export const ${key} = "${buf.toString("base64")}";\n`;
    console.log(`${key}: ${(buf.length / 1024).toFixed(0)}KB from ${rel}`);
  }
  fs.writeFileSync(OUT, out);
  console.log(`wrote ${path.relative(ROOT, OUT)} (${(fs.statSync(OUT).size / 1024 / 1024).toFixed(2)}MB)`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
